<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,t,api,loadWorkspaces,loadData,notify} from '../state'
const router=useRouter(),busy=ref(''),cases=ref<any[]>([])
const preview=computed(()=>cases.value[0])
const activity=computed(()=>Array.from({length:7},(_,i)=>{const day=new Date(Date.now()-(6-i)*86400000).toISOString().slice(0,10);return (preview.value?.dates||[]).filter((d:string)=>d.startsWith(day)).length}))
onMounted(async()=>{try{cases.value=await api('/showcase/summary')}catch{}})
async function demo(variant:string){busy.value=variant;try{const r=await api('/demo',{method:'POST',body:{variant}});sessionStorage.setItem('sd_tour','1');state.user=r.user;await loadWorkspaces(r.workspace_id);await loadData();router.push('/overview')}catch(e:any){notify(e.message,true)}finally{busy.value=''}}
</script>
