<section class="landing-preview" aria-label="Live analysis preview"><div class="preview-bar"><div class="row gap-sm"><span class="preview-dot"></span><span class="preview-dot"></span><span class="preview-dot"></span></div><span>signaldesk / intelligence</span><Icon name="LockKeyhole" :size="12"/></div><div class="preview-body"><div class="row between"><span class="eyebrow">{{t('YOUR BUSINESS, TODAY','ВАШ БИЗНЕС СЕГОДНЯ')}}</span><span class="badge neutral">{{t('Real analysis','Реальный анализ')}}</span></div><h2>{{t('A clearer picture.','Более ясная картина.')}}</h2><p class="muted">{{t('The signals behind your next move.','Сигналы для вашего следующего шага.')}}</p><div class="preview-stat-grid"><div><span>{{t('Signals that matter','Значимые сигналы')}}</span><strong>{{preview?.event_count??'—'}}</strong></div><div><span>{{t('Worth your attention','Требуют внимания')}}</span><strong>{{preview?.risk_count??'—'}}</strong></div></div><div class="preview-chart"><div class="preview-chart-lines"><span>{{Math.max(1,...activity)}}</span><span>0</span></div><div class="preview-bars"><div v-for="(h,i) in activity" :key="i" :style="{height:Math.max(0,h/Math.max(1,...activity)*95)+'%'}"></div></div></div><div class="preview-signal"><div class="row between"><span class="badge risk"><span class="dot"></span>{{preview?.name||t('Company-specific evidence','Источники для вашей компании')}}</span><span class="small muted">{{preview?.events?.[0]?.relevance??'—'}}% {{t('relevant','релевантность')}}</span></div><h3>{{preview?.events?.[0]?.[state.locale]?.title||t('Your next signal starts with your company.','Начните с контекста вашей компании.')}}</h3><p>{{preview?.events?.[0]?.[state.locale]?.why||t('Connect your company to build your own evidence-based view.','Добавьте компанию, чтобы получить анализ на основе источников.')}}</p><div class="preview-action"><span class="spark-icon"><Icon name="Sparkles" :size="15"/></span><span>{{t('A useful next move, backed by evidence.','Полезный следующий шаг на основе источников.')}}</span><Icon name="ArrowUpRight" :size="15"/></div></div></div><div class="preview-floating"><span class="bank-mark">A</span><div><strong>{{t('More than a headline','Больше, чем заголовок')}}</strong><span>{{t('Alfa-Bank research meets your context.','Аналитика Альфа-Банка в контексте компании.')}}</span></div><Icon name="CheckCircle2" :size="18"/></div></section></div>
<div class="landing-strip"><span>{{t('BUILT AROUND YOUR DECISIONS','ВОКРУГ ВАШИХ РЕШЕНИЙ')}}</span><span><Icon name="Building2"/>{{t('Company-aware','Контекст компании')}}</span><span><Icon name="Workflow"/>{{t('Traceable analysis','Проверяемый анализ')}}</span><span><Icon name="FileChartColumn"/>{{t('Daily to monthly briefs','Сводки от дня до месяца')}}</span><span><Icon name="Users"/>{{t('One workspace, many perspectives','Одно пространство, разные роли')}}</span></div>
<section class="landing-steps"><div><span class="eyebrow">{{t('FROM NOISE TO YOUR NEXT MOVE','ОТ ПОТОКА НОВОСТЕЙ К ДЕЙСТВИЮ')}}</span><h2>{{t('Context makes the difference.','Контекст меняет всё.')}}</h2></div><div class="steps-grid"><article v-for="(s,i) in [{icon:'Globe2',title:t('Start with your company','Начните с компании'),body:t('Share your website and what matters to your business. Review the profile before anything is monitored.','Укажите сайт и важные для бизнеса факторы. Проверьте профиль перед началом мониторинга.')},{icon:'Radar',title:t('Keep the right things in view','Следите за тем, что важно'),body:t('Combine trusted news, your own sources and dated bank research. Tune topics and collection rules.','Объединяйте новости, собственные источники и обзоры банка. Настраивайте темы и правила сбора.')},{icon:'ArrowUpRight',title:t('Make the next move clearer','Принимайте обоснованные решения'),body:t('See why an event matters, what might follow and what to check next. Ask a follow-up or share a brief.','Понимайте причины значимости, возможные последствия и следующий шаг. Задавайте вопросы и делитесь сводками.')} ]" :key="i"><span class="step-number">0{{i+1}}</span><Icon :name="s.icon" :size="24"/><h3>{{s.title}}</h3><p>{{s.body}}</p></article></div></section><section class="demo-choice"><div><h3>{{t('Different businesses. Different decisions.','Разный бизнес. Разные решения.')}}</h3><p>{{t('Explore real collected reporting and model analysis. The tour is read-only; a jury account can run the full workflow.','Посмотрите реальные материалы и анализ модели. Гостевой просмотр доступен только для чтения; аккаунт жюри позволяет запускать полный сценарий.')}}</p></div><div class="row gap-sm wrap"><button v-for="c in cases" :key="c.variant" class="btn secondary" :disabled="!!busy" @click="demo(c.variant)"><Icon name="Building2" :size="17"/>{{c.name}}</button><RouterLink to="/login" class="text-link">{{t('Jury / account sign in','Вход для жюри / в аккаунт')}}</RouterLink></div></section><footer class="landing-footer"><span>SignalDesk © 2026 · {{t('Business intelligence by SubSchool','Бизнес-аналитика от SubSchool')}}</span><span>{{t('Facts. Perspective. A more informed decision.','Факты. Контекст. Обоснованное решение.')}}</span></footer></div></template>
